function clue(source){if(!active){toast('Mulai pencarian terlebih dahulu.');return}if(clues<3){clues++;tone(660,.1);updateUI();toast('Petunjuk baru ditemukan melalui '+source+'!')}else toast('Semua petunjuk terkumpul. Periksa taman di dekat air mancur.')}$('#clue-btn').onclick=()=>{modal(`<span class="eyebrow">PETNET • PAPAN WARGA</span><h2>Jejak digital ${pet[0]}</h2><div class="big-emoji">${pet[2]}</div><p>Posting ${ownerName()}: “${pet[0]} kabur dari rumah. Ia memakai kalung merah dan suka bermain di tempat rindang.”</p><p>Lokasi terakhir: ${areas[(level-1)%6]}. Ini adalah papan informasi di dalam game.</p><button class="primary" id="read-clue">Simpan petunjuk internet →</button>`);$('#read-clue').onclick=()=>{close();clue('PetNet')}};
