function inspectTruck(){if(phase!=='captured'){modal('<h2>Polisi Satwa Maple</h2><p>Truk patroli akan mengamankan hewan yang belum ditemukan saat waktu pencarian habis. Di kompartemen tersedia alat penyelamatan untuk misi selanjutnya.</p>');return}modal(`<span class="eyebrow">MISI PENYELAMATAN</span><h2>Bebaskan ${pet[0]}</h2><p>${pet[0]} berada di kandang truk. Pilih alat untuk membuka pengunci, lalu bawa pulang sebelum patroli kembali.</p><div class="shop-grid"><div class="item">🔧<strong>Pengait kompartemen</strong><p>Alat di truk. Membuka pengunci dalam 18 detik.</p><button id="release">Gunakan pengait gratis</button></div><div class="item">✂<strong>Pemotong gembok</strong><p>${inventory.includes('cutter')?'Alatmu membuka pengunci dalam 3 detik.':'Dapat dibeli di toko seharga 200 koin.'}</p><button id="cut" ${inventory.includes('cutter')?'':'disabled'}>Gunakan pemotong</button></div></div>`);let release=cost=>{close();remaining-=cost;if(remaining<=0){lose();return}phase='found';petMesh.visible=true;petMesh.position.copy(player.position).add(new T.Vector3(1,0,0));tone(880,.2);updateUI();toast('Pengunci terbuka! Antar '+pet[0]+' ke '+ownerName()+'.')};$('#release').onclick=()=>release(18);$('#cut').onclick=()=>release(3)}
function win(){active=false;phase='won';money+=reward;rescued++;save();updateUI();tone(784,.2);setTimeout(()=>tone(1046,.3),180);modal(`<div class="big-emoji">${pet[2]} 🏡</div><span class="eyebrow">MISI BERHASIL</span><h2>${pet[0]} akhirnya pulang!</h2><p>${ownerName()} senang sekali. Terima kasih sudah membawa sahabat kecilnya kembali.</p><div class="info-meta"><span>🪙 +${reward} koin</span><span>♡ ${rescued} hewan diselamatkan</span></div><button class="primary" id="next">${level===50?'Rayakan petualangan selesai ✧':'Lanjut ke level '+(level+1)+' →'}</button>`);$('#next').onclick=()=>{close();if(level<50)newLevel(level+1);else{newLevel(1);toast('50 level selesai! Mulai petualangan baru.')}}}
function lose(){active=false;phase='lost';modal(`<div class="big-emoji">🚚</div><h2>Patroli sudah kembali</h2><p>Waktu penyelamatan habis. ${pet[0]} dibawa ke penangkaran. Coba lagi dengan petunjuk yang sudah kamu pelajari.</p><button id="retry" class="primary">Coba level ini lagi →</button>`);$('#retry').onclick=()=>{close();newLevel(level)}}
const shopItems=[['bike','🚲','Sepeda',180,'Langkah 1,6× lebih cepat dengan WASD.'],['board','🛹','Skateboard',120,'Langkah 1,3× lebih cepat.'],['cutter','✂️','Pemotong gembok',200,'Buka kandang truk hanya dalam 3 detik.'],['torch','🔥','Las mini',240,'Menambah 25 detik waktu penyelamatan.'],['jet','🚀','Jetpack',600,'Bergerak 2,5× lebih cepat.'],['infra','🥽','Kacamata infrared',300,'Hewan disorot dengan penanda hijau.'],['digital','🗺️','Digital map',220,'Tampilkan lokasi hewan pada peta.'],['hound','🐕‍🦺','Anjing pelacak',350,'Buka semua petunjuk saat misi dimulai.']];
function shop(){modal(`<span class="eyebrow">BEKAL PENJELAJAH</span><h2>Toko peralatan</h2><p>Saldo kamu: 🪙 ${money} koin. Peralatan yang dibeli langsung aktif dan tersimpan di browser ini.</p><div class="shop-grid">${shopItems.map(([id,emoji,name,price,desc])=>`<div class="item">${emoji}<strong>${name}</strong><p>${desc}</p><button data-buy="${id}" ${inventory.includes(id)||money<price?'disabled':''}>${inventory.includes(id)?'✓ Sudah dimiliki':price+' koin • Beli'}</button></div>`).join('')}</div>`);document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{let item=shopItems.find(i=>i[0]===b.dataset.buy);if(money>=item[3]&&!inventory.includes(item[0])){money-=item[3];inventory.push(item[0]);save();updateUI();shop();tone(880,.12)}})}
function levels(){modal(`<span class="eyebrow">PETA PETUALANGAN</span><h2>50 kesempatan untuk jadi pahlawan</h2><p>Enam lingkungan, hewan berbeda, dan waktu pencarian yang semakin singkat. Pilih level untuk bermain.</p><div class="level-grid">${Array.from({length:50},(_,i)=>`<button data-level="${i+1}" class="${level===i+1?'current':''}" title="${areas[i%6]} · ${animals[i][1]}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div>`);document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{close();newLevel(+b.dataset.level)})}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(b.dataset.tab==='shop')shop();else if(b.dataset.tab==='levels')levels();else close()});$('#help').onclick=()=>modal(`<span class="eyebrow">PANDUAN BERMAIN</span><h2>Petualangan dimulai dari rasa ingin tahu.</h2><p>1. Tekan <b>Mulai pencarian</b> untuk menjalankan waktu.<br>2. Klik brosur di tiang atau pohon, tanya warga, dan buka PetNet untuk mendapatkan petunjuk.<br>3. Drag untuk memutar kota, scroll atau tombol +/− untuk zoom. Gunakan <b>WASD / tombol panah</b> untuk bergerak.<br>4. Klik hewan berkalung merah untuk menjemputnya, lalu klik rumah pemilik atau <b>Antar ke pemilik</b>.<br>5. Saat waktu habis, hewan masuk truk. Buka kompartemen, pilih alat, dan selesaikan penyelamatan sebelum patroli kembali.</p><p>Klik ♫ untuk musik dan efek suara. Jam kota mengikuti waktu riil Jakarta (WIB). Kemajuan tersimpan otomatis di browser.</p>`);
$('#map').onclick=()=>{modal(`<span class="eyebrow">PETA ${areas[(level-1)%6].toUpperCase()}</span><h2>Ke mana kita?</h2><p>Pilih lokasi untuk memusatkan kamera.${inventory.includes('digital')?' 🐾 Hewan terdeteksi di taman!':''}</p><div class="map-grid"><button data-place="office">🏙 Perkantoran</button><button data-place="park">🌳 Taman${inventory.includes('digital')?' 🐾':''}</button><button data-place="river">🎣 Sungai</button><button data-place="owner">🏡 Rumah pemilik</button><button data-place="shops">🛍 Pertokoan</button><button data-place="truck">🚚 Polisi satwa</button></div>`);document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{let p={office:[-22,0,-10],park:[8,0,-1],river:[27,0,0],owner:ownerPos.toArray(),shops:[8,0,19],truck:truckPos.toArray()}[b.dataset.place];target.fromArray(p);distance=38;close()})};
function inspect(o){target.copy(o.position);distance=30;let d=o.userData;if(d.type==='pet'){if(!active){toast('Mulai pencarian terlebih dahulu.');return}if(phase==='captured'){toast('Hewan sudah dibawa ke truk polisi satwa.');return}if(phase==='found'){toast('Antar '+pet[0]+' ke pemiliknya.');return}phase='found';tone(1046,.2);updateUI();modal(`<div class="big-emoji">${pet[2]}</div><span class="eyebrow">SAHABAT DITEMUKAN</span><h2>Hai, ${pet[0]}!</h2><p>Kalung merahnya cocok dengan petunjuk. ${pet[0]} sekarang mengikuti kamu. Antar ke ${ownerName()} di dekat pertokoan.</p><button class="primary" id="home">Antar ke pemilik ⌂</button>`);$('#home').onclick=()=>{close();inspectOwner()};return}if(d.type==='owner'){inspectOwner();return}if(d.type==='truck'){inspectTruck();return}modal(`<span class="eyebrow">JELAJAHI KOTA</span><h2>${d.name}</h2><div class="info-meta"><span>Pemilik: ${d.owner}</span><span>Area: ${areas[(level-1)%6]}</span></div><p>${d.detail}</p>${['poster','person','tree'].includes(d.type)?'<button class="primary" id="ask">'+(d.type==='person'?'Tanya warga':'Baca brosur')+' →</button>':''}`);if($('#ask'))$('#ask').onclick=()=>{close();clue(d.name)}}
let pointer={x:0,y:0,drag:false,down:false},ray=new T.Raycaster(),mouse=new T.Vector2();let hovered;renderer.domElement.addEventListener('pointerdown',e=>{pointer={x:e.clientX,y:e.clientY,drag:false,down:true};renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointermove',e=>{if(pointer.down){let dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(Math.abs(dx)+Math.abs(dy)>3)pointer.drag=true;angle-=dx*.006;distance=Math.max(18,Math.min(110,distance+dy*.05));pointer.x=e.clientX;pointer.y=e.clientY}else{let rect=renderer.domElement.getBoundingClientRect();mouse.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);ray.setFromCamera(mouse,camera);renderer.domElement.style.cursor=ray.intersectObjects(targets,true).length?'pointer':'grab'}});renderer.domElement.addEventListener('pointerup',e=>{if(!pointer.drag){let r=renderer.domElement.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);let hit=ray.intersectObjects(targets,true)[0];if(hit){let o=hit.object;while(o.parent&& !o.userData.type)o=o.parent;if(o.userData.type)inspect(o)}}pointer.down=false});renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();distance=Math.max(18,Math.min(110,distance+e.deltaY*.04))},{passive:false});$('#zoomin').onclick=()=>distance=Math.max(18,distance-8);$('#zoomout').onclick=()=>distance=Math.min(110,distance+8);$('#resetcam').onclick=()=>{angle=.76;distance=77;target.set(0,0,0)};
const keys=new Set();document.addEventListener('keydown',e=>{if($('#modal').hidden&&['w','a','s','d','ArrowUp','ArrowLeft','ArrowDown','ArrowRight'].includes(e.key)){e.preventDefault();keys.add(e.key)}});document.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>keys.clear());let mobile=document.createElement('div');mobile.className='mobile-controls';mobile.innerHTML='<button aria-label="Berjalan ke kiri">←</button><button aria-label="Berjalan maju">↑</button><button aria-label="Berjalan mundur">↓</button><button aria-label="Berjalan ke kanan">→</button>';$('.world-wrap').appendChild(mobile);[...mobile.children].forEach((b,i)=>{b.onpointerdown=e=>{e.preventDefault();keys.add(['a','w','s','d'][i]);b.setPointerCapture(e.pointerId)};b.onpointerup=b.onpointercancel=()=>keys.clear()});
function initAudio(){if(!audio){audio=new (window.AudioContext||window.webkitAudioContext)()}if(audio.state==='suspended')audio.resume()}function tone(f,d=.12,type='sine',vol=.035){if(muted||!audio)return;let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=f;g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+d)}$('#sound').onclick=()=>{initAudio();muted=!muted;$('#sound').textContent=muted?'♫':'♪';$('#sound').setAttribute('aria-label',muted?'Aktifkan suara':'Matikan suara');toast(muted?'Suara dimatikan':'Musik ceria dan suasana kota diaktifkan');tone(523,.2)};let note=0;const melody=[523,659,784,659,587,698,880,698,523,659,784,1046,880,784,659,587];
function tickClock(){let d=new Date(),h=Number(d.toLocaleString('en-GB',{hour:'2-digit',hourCycle:'h23',timeZone:'Asia/Jakarta'}));$('#clock').textContent=d.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Jakarta'});let period=h>=5&&h<11?'Pagi':h>=11&&h<15?'Siang':h>=15&&h<18?'Sore':'Malam';$('#period').textContent=period;$('.weather').firstChild.textContent=period==='Malam'?'☾ ':'☀ ';let night=period==='Malam';ambient.intensity=night?.95:2.4;sun.intensity=night?.45:period==='Sore'?2.1:3.1;scene.background.set(night?0x5c7475:period==='Sore'?0xe4d5ba:0xdce6d2);scene.fog.color.copy(scene.background)}setInterval(tickClock,10000);
function resize(){let el=$('#world');camera.aspect=el.clientWidth/el.clientHeight;camera.updateProjectionMatrix();renderer.setSize(el.clientWidth,el.clientHeight)}new ResizeObserver(resize).observe($('#world'));
let accum=0;function frame(t){requestAnimationFrame(frame);let dt=Math.min((t-lastTime)/1000,.05);lastTime=t;let sec=t/1000;camTarget.lerp(target,.06);camera.position.set(camTarget.x+Math.sin(angle)*distance,camTarget.y+distance*.77,camTarget.z+Math.cos(angle)*distance);camera.lookAt(camTarget.x,camTarget.y+1,camTarget.z);for(let tr of trees)tr.rotation.z=Math.sin(sec*1.3+tr.position.x)*.018;for(let c of cars){c.mesh.position.x+=dt*c.speed*c.dir;if(c.mesh.position.x>30)c.mesh.position.x=-30;if(c.mesh.position.x< -30)c.mesh.position.x=30;c.mesh.rotation.y=c.dir<0?Math.PI:0}for(let p of people)if(!p.fisher&&p.mesh!==player&&p.mesh.userData.type!=='owner'){p.mesh.position.x=p.x+Math.sin(sec*.17+p.offset)*2;p.mesh.position.y=Math.abs(Math.sin(sec*3+p.offset))*.06}for(let w of waters){w.position.z+=dt*1.2;if(w.position.z>26)w.position.z=-26}if(petMesh&&phase!=='captured'){if(phase==='found'){petMesh.position.lerp(player.position.clone().add(new T.Vector3(1.3,0,0)),.04)}petMesh.position.y=.04+Math.sin(sec*3)*.06;if(inventory.includes('infra')){petMesh.children.forEach(o=>{if(o.material?.emissive)o.material.emissive.setHex(0x123600)})}}
if(active&&!paused&&!document.hidden){accum+=dt;if(accum>=1){remaining-=Math.floor(accum);accum%=1;if(remaining<=0){if(phase==='captured'||phase==='found'){lose()}else{phase='captured';remaining=70+ (inventory.includes('torch')?25:0);petMesh.visible=false;updateUI();toast('Polisi satwa mengamankan '+pet[0]+'. Buka truk untuk menyelamatkannya!')}}}let speed=(inventory.includes('jet')?2.5:inventory.includes('bike')?1.6:inventory.includes('board')?1.3:1)*5*dt;let dx=(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0),dz=(keys.has('s')||keys.has('ArrowDown')?1:0)-(keys.has('w')||keys.has('ArrowUp')?1:0);if(dx||dz){player.position.x=T.MathUtils.clamp(player.position.x+dx*speed,-30,22);player.position.z=T.MathUtils.clamp(player.position.z+dz*speed,-24,24);player.position.y=Math.abs(Math.sin(sec*10))*.15;target.copy(player.position);if(phase==='found'&&player.position.distanceTo(ownerPos)<2.5)win()}if(inventory.includes('hound')&&clues<3){clues=3;updateUI()}}
$('#timer').textContent=String(Math.max(0,Math.floor(remaining/60))).padStart(2,'0')+':'+String(Math.max(0,Math.floor(remaining%60))).padStart(2,'0');$('#timer-bar').style.width=Math.min(100,remaining/(phase==='captured'?95:Math.max(95,305-level*4))*100)+'%';if(audio&&!muted&&sec-lastSound>.36){lastSound=sec;tone(melody[note++%melody.length],.27,'sine',.018);if(note%23===0){tone(220,.18,'triangle',.025);setTimeout(()=>tone(277,.15,'triangle',.02),180)}if(note%37===0){tone(450,.09,'sine',.02);setTimeout(()=>tone(600,.1,'sine',.02),120)}}renderer.render(scene,camera)}
newLevel(level);resize();requestAnimationFrame(frame);setTimeout(()=>toast('Selamat datang! Klik “Mulai pencarian” untuk mencari '+pet[0]+'.'),800);
